public class LocalTranslationEditor:Form {
 readonly LocalRun run;readonly Color bg,card,paper,accent;readonly DataGridView grid=new DataGridView();readonly TextBox search=new TextBox(),native=new TextBox(),english=new TextBox(),target=new TextBox();readonly ComboBox layer=new ComboBox();readonly Label status=new Label();readonly FlowLayoutPanel tools=new FlowLayoutPanel(),filters=new FlowLayoutPanel();readonly Dictionary<string,CheckBox> originFilters=new Dictionary<string,CheckBox>();HashSet<string> importedSources=new HashSet<string>(),userSources=new HashSet<string>();readonly SleekButton save=new SleekButton(),discard=new SleekButton();readonly System.Windows.Forms.Timer debounce=new System.Windows.Forms.Timer();
 LocalComparison data=new LocalComparison();Dictionary<string,string> covered=new Dictionary<string,string>();LocalRunOptions options;List<LocalUnit> all=new List<LocalUnit>(),shown=new List<LocalUnit>();HashSet<string> selected=new HashSet<string>();Dictionary<string,string> failures=new Dictionary<string,string>();LocalUnit current;bool busy,setting,filtering;string view="effective";
 public LocalTranslationEditor(LocalRun value,Color background,Color panel,Color text,Color color){run=value;bg=background;card=panel;paper=text;accent=color;Text="Translation comparison · "+run.Name;ClientSize=new Size(1160,760);MinimumSize=new Size(1000,650);StartPosition=FormStartPosition.CenterParent;BackColor=bg;ForeColor=paper;Font=new Font("Segoe UI",10);
  search.PlaceholderTextCompat("Search source, English, target, category or status");Controls.Add(search);search.TextChanged+=delegate{debounce.Stop();debounce.Start();};debounce.Interval=250;debounce.Tick+=delegate{debounce.Stop();Filter();};layer.DropDownStyle=ComboBoxStyle.DropDownList;layer.DisplayMember="Value";Controls.Add(layer);layer.SelectedIndexChanged+=delegate{if(setting||layer.SelectedItem==null)return;view=((KeyValuePair<string,string>)layer.SelectedItem).Key;grid.Columns[3].HeaderText="Target · "+((KeyValuePair<string,string>)layer.SelectedItem).Value;grid.Invalidate();if(!target.Modified)SelectRow();};
  tools.WrapContents=false;Controls.Add(tools);AddTool("Refresh",async()=>await Reload());AddTool("Import",async()=>await Import());AddTool("Export",()=>{ExportMenu();return Task.FromResult(0);});AddTool("Glossary",async()=>{using(var dialog=new LocalGlossaryWindow(run,bg,card,paper,accent))dialog.ShowDialog(this);await Reload();});AddTool("Dictionaries",async()=>{using(var dialog=new LocalPackWindow(run,bg,card,paper,accent))dialog.ShowDialog(this);await Reload();});AddTool("Use this layer",async()=>{await Work(()=>{var next=LocalTranslation.Options(run);next.RenderLayer=view;LocalTranslation.SetOptions(run.Id,next);LocalLibrary.Publish(run);});});AddTool("Selected ▾",()=>{BulkMenu();return Task.FromResult(0);});
  filters.WrapContents=false;filters.Controls.Add(new Label{Text="Show:",AutoSize=true,Margin=new Padding(0,6,12,0)});foreach(var pair in new[]{new KeyValuePair<string,string>("untranslated","Untranslated"),new KeyValuePair<string,string>("model","Local model"),new KeyValuePair<string,string>("user","User corrected"),new KeyValuePair<string,string>("imported","Imported")}){var filter=new CheckBox{Text=pair.Value,Checked=true,AutoSize=true,Appearance=Appearance.Button,FlatStyle=FlatStyle.Flat,BackColor=card,ForeColor=paper,Margin=new Padding(0,0,10,0),Padding=new Padding(8,2,8,2)};filter.FlatAppearance.BorderColor=accent;filter.CheckedChanged+=delegate{Filter();};originFilters[pair.Key]=filter;filters.Controls.Add(filter);}Controls.Add(filters);
   grid.VirtualMode=true;grid.ReadOnly=true;grid.AllowUserToAddRows=grid.AllowUserToDeleteRows=false;grid.RowHeadersVisible=false;grid.MultiSelect=true;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;grid.BackgroundColor=card;grid.BorderStyle=BorderStyle.None;grid.EnableHeadersVisualStyles=false;grid.DefaultCellStyle.BackColor=card;grid.DefaultCellStyle.ForeColor=paper;grid.DefaultCellStyle.SelectionBackColor=accent;grid.ColumnHeadersDefaultCellStyle.BackColor=bg;grid.ColumnHeadersDefaultCellStyle.ForeColor=paper;grid.ColumnHeadersHeight=30;
  foreach(string name in new[]{"State","Native source","Curated English","Target · Effective"})grid.Columns.Add(new DataGridViewTextBoxColumn{HeaderText=name,FillWeight=name=="State"?42:100,MinimumWidth=name=="State"?110:180,SortMode=DataGridViewColumnSortMode.NotSortable});
  grid.CellValueNeeded+=delegate(object sender,DataGridViewCellValueEventArgs e){if(e.RowIndex>=shown.Count)return;var row=shown[e.RowIndex];e.Value=e.ColumnIndex==0?State(row):Preview(e.ColumnIndex==1?row.Source:e.ColumnIndex==2?Get(data.English,row.Source):Target(row.Source));};grid.SelectionChanged+=delegate{if(filtering)return;var visible=new HashSet<string>(shown.Select(x=>x.Key));selected.RemoveWhere(x=>visible.Contains(x));foreach(DataGridViewRow row in grid.SelectedRows)if(row.Index<shown.Count)selected.Add(shown[row.Index].Key);};grid.CurrentCellChanged+=delegate{if(!filtering)SelectRow();};Controls.Add(grid);
  foreach(var box in new[]{native,english,target}){box.Multiline=true;box.ScrollBars=ScrollBars.Vertical;box.BackColor=card;box.ForeColor=paper;Controls.Add(box);}native.ReadOnly=english.ReadOnly=true;
  save.Text="Save user override";save.Primary=true;save.BackColor=accent;save.ForeColor=paper;save.Click+=async delegate{try{await Save();}catch(Exception e){status.Text=e.Message;}};Controls.Add(save);discard.Text="Discard typed edit";discard.BackColor=card;discard.ForeColor=paper;discard.Click+=delegate{target.Modified=false;Filter();};Controls.Add(discard);Controls.Add(status);
  Resize+=delegate{Arrange();};Shown+=async delegate{await Reload();};FormClosing+=delegate(object sender,FormClosingEventArgs e){if(busy){e.Cancel=true;status.Text="Wait for the current dictionary operation to finish.";return;}if(target.Modified&&MessageBox.Show(this,"Discard the unsaved typed edit?","Unsaved translation",MessageBoxButtons.YesNo)!=DialogResult.Yes)e.Cancel=true;};FormClosed+=delegate{debounce.Stop();debounce.Dispose();};Arrange();
 }
 void AddTool(string text,Func<Task> action){var button=new SleekButton{Text=text,BackColor=card,ForeColor=paper,Width=text=="Use this layer"?136:text=="Dictionaries"?126:108,Height=34,Margin=new Padding(0,0,8,0)};button.Click+=async delegate{if(busy)return;try{await action();}catch(Exception e){if(!IsDisposed)status.Text=e.Message;}};tools.Controls.Add(button);}
 void Arrange(){int w=ClientSize.Width,h=ClientSize.Height;search.SetBounds(18,15,w-330,29);layer.SetBounds(w-296,15,278,29);tools.SetBounds(18,56,w-36,37);filters.SetBounds(18,98,w-36,30);grid.SetBounds(18,140,w-36,Math.Max(150,h-399));int width=(w-56)/3;native.SetBounds(18,h-246,width,155);english.SetBounds(native.Right+10,h-246,width,155);target.SetBounds(english.Right+10,h-246,width,155);discard.SetBounds(w-370,h-76,166,34);save.SetBounds(w-194,h-76,176,34);status.SetBounds(18,h-35,w-36,28);}
 static string Get(Dictionary<string,string> map,string key){string value;return map.TryGetValue(key,out value)?value:"";}
 static string Preview(string value){value=(value??"").Replace("\n"," ↵ ");return value.Length>600?value.Substring(0,600)+"…":value;}
 string Target(string source){return Get(LocalLibrary.Layer(data,view),source);}
 string State(LocalUnit row){string role;if(!covered.TryGetValue(row.Source,out role))return "Inactive legacy";LocalEdit edit;if(data.Edits.TryGetValue(row.Key,out edit)){if(edit.LeaveOriginal)return "Original";if(edit.Deferred)return "Deferred";if(edit.Target!=null)return "User override";}if(!LocalLibrary.Selected(options,role,row.Source))return "Excluded";if(data.User.ContainsKey(row.Source))return "User override";if(data.Imported.ContainsKey(row.Source))return "Imported";LocalResult result;if(data.ModelRows.TryGetValue(row.Source,out result)){if(!string.IsNullOrEmpty(result.ReferenceHash)&&result.ReferenceHash!=LocalTranslation.TextHash(Get(data.English,row.Source)))return "English updated";if(string.IsNullOrEmpty(result.PolicyHash))return "Legacy model";return "Model";}return failures.ContainsKey(row.Key)?"Failed / deferred":"Pending";}
 async Task Reload(){if(busy)return;if(target.Modified){status.Text="Save or discard your typed edit before refreshing.";return;}busy=true;status.Text="Loading comparison…";try{
   LocalComparison next=null;Dictionary<string,string> scope=null,errors=null;LocalRunOptions settings=null;await Task.Run(()=>{scope=EnglishSupport.CoveredLocalSources(run.Root);next=LocalLibrary.Compare(run);settings=LocalTranslation.Options(run);errors=LocalTranslation.Read<Dictionary<string,string>>(LocalTranslation.RunFile(run.Id,"failures.json"));});if(IsDisposed)return;data=next;covered=scope;options=settings;failures=errors;all=covered.Select(x=>new LocalUnit{Source=x.Key,Category=x.Value,Context="EnglishCoverage",Key=LocalLibrary.Key(x.Value,x.Key)}).ToList();foreach(var row in data.ModelRows.Values.Where(x=>!covered.ContainsKey(x.Source)))all.Add(row);importedSources=new HashSet<string>(data.Packs.Values.SelectMany(x=>x.Entries).Select(x=>x.Source));userSources=new HashSet<string>(data.Edits.Values.Where(x=>!string.IsNullOrEmpty(x.Target)).Select(x=>x.Source));var known=new HashSet<string>(all.Select(x=>x.Source));foreach(var row in data.Packs.Values.SelectMany(x=>x.Entries))if(!known.Contains(row.Source)){string role=row.Role??"Inactive";all.Add(new LocalUnit{Source=row.Source,Category=role,Context="EnglishCoverage",Key=LocalLibrary.Key(role,row.Source)});known.Add(row.Source);}
   setting=true;layer.Items.Clear();foreach(var pair in new[]{new KeyValuePair<string,string>("effective","Effective (user > imports > model)"),new KeyValuePair<string,string>("model","Model output"),new KeyValuePair<string,string>("imported","Selected imported dictionaries"),new KeyValuePair<string,string>("user","User overrides")})layer.Items.Add(pair);foreach(var pack in data.Packs.Values)layer.Items.Add(new KeyValuePair<string,string>("pack:"+pack.Id,"Imported: "+pack.Name));layer.SelectedItem=layer.Items.Cast<KeyValuePair<string,string>>().FirstOrDefault(x=>x.Key==view);if(layer.SelectedIndex<0)layer.SelectedIndex=0;setting=false;Filter();
  }catch(Exception e){if(!IsDisposed)status.Text=e.Message;}finally{busy=false;}}
 bool OriginVisible(string source){bool model=data.Model.ContainsKey(source),user=userSources.Contains(source),imported=importedSources.Contains(source);return originFilters["model"].Checked&&model||originFilters["user"].Checked&&user||originFilters["imported"].Checked&&imported||originFilters["untranslated"].Checked&&!model&&!user&&!imported;}
  void Filter(){if(target.Modified){status.Text="Your unsaved edit is kept; save/discard it before changing the filter.";return;}string query=search.Text.Trim();var targets=LocalLibrary.Layer(data,view);shown=all.Where(x=>OriginVisible(x.Source)&&(query.Length==0||x.Source.IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0||Get(data.English,x.Source).IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0||Get(targets,x.Source).IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0||x.Category.IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0||State(x).IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0)).ToList();filtering=true;grid.RowCount=shown.Count;grid.ClearSelection();var indices=shown.Select((x,i)=>new{key=x.Key,index=i}).ToDictionary(x=>x.key,x=>x.index);foreach(string key in selected){int index;if(indices.TryGetValue(key,out index))grid.Rows[index].Selected=true;}filtering=false;grid.Invalidate();status.Text=shown.Count.ToString("N0")+" rows · "+selected.Count+" selected (including hidden rows) · matching any checked origin · Ctrl/Shift selects ranges";SelectRow();}
 void SelectRow(){if(grid.CurrentCell==null||grid.CurrentCell.RowIndex>=shown.Count)return;if(target.Modified){status.Text="Unsaved edit remains bound to the source shown below. Save or discard it first.";return;}current=shown[grid.CurrentCell.RowIndex];setting=true;native.Text=current.Source;english.Text=Get(data.English,current.Source);target.Text=Target(current.Source);target.Modified=false;setting=false;save.Enabled=covered.ContainsKey(current.Source);status.Text=State(current)+" · "+current.Category+" · "+current.Context+" · "+selected.Count+" selected";}
 async Task Save(){if(busy||current==null)return;var row=current;string text=target.Text;if(string.IsNullOrWhiteSpace(text)){status.Text="Enter a translation; use Selected ▾ to leave original or defer.";return;}await Work(()=>LocalTranslation.Edit(run.Id,new LocalEdit{Key=row.Key,Source=row.Source,Category=row.Category,Context="EnglishCoverage",Target=text}));target.Modified=false;await Reload();}
 async Task Work(Action action){if(busy)return;busy=true;save.Enabled=false;try{await Task.Run(action);if(!IsDisposed)status.Text="Saved · model output, imported text and authored overrides are retained separately";}catch(Exception e){if(!IsDisposed)status.Text=e.Message;throw;}finally{busy=false;if(!IsDisposed)save.Enabled=current!=null&&covered.ContainsKey(current.Source);}}
 List<LocalUnit> Selection(){var rows=all.Where(x=>selected.Contains(x.Key)).ToList();if(rows.Count==0&&current!=null)rows.Add(current);return rows;}
 void BulkMenu(){if(target.Modified){status.Text="Save/discard the typed edit before a batch action.";return;}var menu=new ContextMenuStrip();menu.Items.Add("Clear selection (including hidden rows)",null,delegate{selected.Clear();Filter();});menu.Items.Add(new ToolStripSeparator());foreach(var pair in new[]{new KeyValuePair<string,string>("queue","Queue selected pending entries"),new KeyValuePair<string,string>("regenerate","Regenerate selected model text"),new KeyValuePair<string,string>("defer","Defer selected"),new KeyValuePair<string,string>("original","Leave selected original"),new KeyValuePair<string,string>("clear","Clear selected user overrides")}){var command=pair;menu.Items.Add(command.Value,null,async delegate{try{var rows=Selection();if(command.Key=="regenerate"&&MessageBox.Show(this,"Regenerate model text for "+rows.Count+" selected entries? Existing authored/imported text keeps precedence; old model output is retained until replacements finish.","Regenerate selected",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;await Work(()=>LocalLibrary.Batch(run,rows,command.Key));await Reload();}catch(Exception e){status.Text=e.Message;}});}menu.Closed+=delegate{menu.Dispose();};menu.Show(Cursor.Position);}
 void ExportMenu(){var menu=new ContextMenuStrip();menu.Items.Add("Export selected ("+Selection().Count+")",null,async delegate{await Export(Selection());});menu.Items.Add("Export all filtered ("+shown.Count+")",null,async delegate{await Export(shown.ToList());});menu.Closed+=delegate{menu.Dispose();};menu.Show(Cursor.Position);}
 async Task Export(List<LocalUnit> rows){try{using(var picker=new SaveFileDialog{Title="Export "+view+" dictionary · "+run.Language,Filter="Portable dictionary JSON|*.json",FileName="Celesphonia-"+run.Language+"-dictionary.json"}){if(picker.ShowDialog(this)!=DialogResult.OK)return;bool profile=MessageBox.Show(this,"Include this run's glossary/context profile too? Choose No to share translations only.","Optional glossary export",MessageBoxButtons.YesNo)==DialogResult.Yes;string file=picker.FileName;await Work(()=>LocalLibrary.Export(file,run,rows.Select(x=>x.Source),view,profile));status.Text="Exported portable dictionary · no install paths, saves, models or adapter scripts included";}}catch(Exception e){status.Text=e.Message;}}
 async Task Import(){if(target.Modified){status.Text="Save/discard the typed edit before importing.";return;}try{using(var picker=new OpenFileDialog{Title="Import dictionary for "+run.Language+" · "+run.OriginVersion,Filter="Dictionary files|*.json;*.jsonl;*.zip|All files|*.*"}){if(picker.ShowDialog(this)!=DialogResult.OK)return;LocalImportPreview preview=null;string file=picker.FileName;await Work(()=>preview=LocalLibrary.Parse(file,run));using(var dialog=new LocalImportDialog(preview,bg,card,paper,accent)){if(dialog.ShowDialog(this)!=DialogResult.OK)return;bool enable=dialog.EnableDictionary,glossary=dialog.UseGlossary;await Work(()=>{LocalLibrary.Import(run,preview,enable);if(glossary&&preview.Pack.Glossary!=null){var p=preview.Pack.Glossary;p.Id="pack-"+preview.Pack.Id;p.Language=run.Language;LocalLibrary.SaveProfile(p);var settings=LocalTranslation.Options(run);settings.GlossaryProfileId=p.Id;LocalTranslation.SetOptions(run.Id,settings);}});}await Reload();}}catch(Exception e){status.Text=e.Message;}}
}

public class LocalImportDialog:Form {
 readonly CheckBox enable=new CheckBox(),glossary=new CheckBox();public bool EnableDictionary{get{return enable.Checked;}}public bool UseGlossary{get{return glossary.Checked;}}
 public LocalImportDialog(LocalImportPreview preview,Color bg,Color card,Color text,Color accent){Text="Import preview · "+preview.Pack.Name;ClientSize=new Size(600,360);StartPosition=FormStartPosition.CenterParent;BackColor=bg;ForeColor=text;Font=new Font("Segoe UI",10);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;Controls.Add(new Label{Text=preview.Summary,Location=new Point(24,22),Size=new Size(550,180)});enable.Text="Enable this dictionary for this run";enable.Checked=true;enable.SetBounds(24,213,550,28);Controls.Add(enable);glossary.Text="Use the included glossary/context profile";glossary.Enabled=preview.Pack.Glossary!=null;glossary.SetBounds(24,252,550,28);Controls.Add(glossary);var apply=new SleekButton{Text="Import",Primary=true,BackColor=accent,ForeColor=text,Location=new Point(414,302),Size=new Size(160,36)};apply.Click+=delegate{DialogResult=DialogResult.OK;};Controls.Add(apply);AcceptButton=apply;}
}

public class LocalPackWindow:Form {
 readonly LocalRun run;readonly CheckedListBox list=new CheckedListBox();readonly Label details=new Label();
 public LocalPackWindow(LocalRun value,Color bg,Color card,Color text,Color accent){run=value;Text="Dictionaries · "+run.Language;ClientSize=new Size(720,470);StartPosition=FormStartPosition.CenterParent;BackColor=bg;ForeColor=text;Font=new Font("Segoe UI",10);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;var options=LocalTranslation.Options(run);list.CheckOnClick=true;list.BackColor=card;list.ForeColor=text;list.BorderStyle=BorderStyle.None;list.SetBounds(24,24,672,286);foreach(var pack in LocalLibrary.Packs(run))list.Items.Add(pack,(options.PackIds??new string[0]).Contains(pack.Id));Controls.Add(list);details.SetBounds(24,326,672,74);details.Text="Checked dictionaries feed the Imported layer. User overrides always take precedence.\r\nDisabling a dictionary keeps its data for later versions.\r\nUse the target selector in the comparison window to inspect each pack separately.";Controls.Add(details);var save=new SleekButton{Text="Use checked dictionaries",Primary=true,BackColor=accent,ForeColor=text,Location=new Point(430,414),Size=new Size(266,36)};save.Click+=async delegate{save.Enabled=false;try{var selected=list.CheckedItems.Cast<LocalDictionaryPack>().Select(x=>x.Id).ToArray();await Task.Run(()=>{var next=LocalTranslation.Options(run);next.PackIds=selected;LocalTranslation.SetOptions(run.Id,next);LocalLibrary.Publish(run);});DialogResult=DialogResult.OK;}catch(Exception e){details.Text=e.Message;save.Enabled=true;}};Controls.Add(save);}
}

public class LocalGlossaryWindow:Form {
 readonly LocalRun run;readonly ComboBox profiles=new ComboBox();readonly TextBox name=new TextBox(),context=new TextBox();readonly DataGridView terms=new DataGridView();readonly CheckBox english=new CheckBox(),enabled=new CheckBox();readonly Label status=new Label();readonly SleekButton save=new SleekButton(),refresh=new SleekButton();bool busy;
 public LocalGlossaryWindow(LocalRun value,Color bg,Color card,Color text,Color accent){run=value;Text="Glossary & context · "+run.Language;ClientSize=new Size(850,700);MinimumSize=new Size(760,650);StartPosition=FormStartPosition.CenterParent;BackColor=bg;ForeColor=text;Font=new Font("Segoe UI",10);profiles.DropDownStyle=ComboBoxStyle.DropDownList;profiles.DisplayMember="Name";Controls.Add(profiles);name.BackColor=context.BackColor=card;name.ForeColor=context.ForeColor=text;Controls.Add(name);context.Multiline=true;context.ScrollBars=ScrollBars.Vertical;Controls.Add(context);english.Text="Use curated English as a meaning reference";enabled.Text="Send matching glossary terms to PLaMo";Controls.Add(english);Controls.Add(enabled);terms.BackgroundColor=card;terms.DefaultCellStyle.BackColor=card;terms.DefaultCellStyle.ForeColor=text;terms.DefaultCellStyle.SelectionBackColor=accent;terms.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;terms.RowHeadersVisible=false;terms.Columns.Add("source","Source term");terms.Columns.Add("target","Target term");Controls.Add(terms);Controls.Add(status);
  save.Text="Save profile & use";save.Primary=true;save.BackColor=accent;save.ForeColor=text;save.Click+=async delegate{try{await Save();}catch(Exception e){status.Text=e.Message;}};Controls.Add(save);refresh.Text="Refresh affected model text";refresh.BackColor=card;refresh.ForeColor=text;refresh.Click+=async delegate{if(busy)return;try{await Save();busy=true;var comparison=await Task.Run(()=>LocalLibrary.Compare(run));var options=LocalTranslation.Options(run);var profile=LocalLibrary.Profile(run,options);var covered=EnglishSupport.CoveredLocalSources(run.Root);var affected=comparison.ModelRows.Values.Where(x=>covered.ContainsKey(x.Source)&&LocalLibrary.Selected(options,covered[x.Source],x.Source)&&!comparison.User.ContainsKey(x.Source)&&!comparison.Imported.ContainsKey(x.Source)&&(string.IsNullOrEmpty(x.PolicyHash)?profile.Terms.Any(t=>x.Source.IndexOf(t.Source,StringComparison.OrdinalIgnoreCase)>=0&&x.Target.IndexOf(t.Target,StringComparison.OrdinalIgnoreCase)<0):x.PolicyHash!=LocalLibrary.Policy(run,options,x.Source,comparison.English.ContainsKey(x.Source)?comparison.English[x.Source]:""))).Select(x=>new LocalUnit{Key=LocalLibrary.Key(covered[x.Source],x.Source),Source=x.Source,Category=covered[x.Source],Context="EnglishCoverage"}).ToList();if(affected.Count==0){status.Text="No affected cached model entries found.";return;}if(MessageBox.Show(this,"Queue "+affected.Count+" affected model entries? Old output remains available until replacements finish; manual/imported text is kept.","Refresh affected",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;await Task.Run(()=>LocalLibrary.Batch(run,affected,"regenerate"));status.Text=affected.Count+" affected entries queued; completed unrelated work is retained.";}catch(Exception e){status.Text=e.Message;}finally{busy=false;}};Controls.Add(refresh);
  profiles.SelectedIndexChanged+=delegate{if(profiles.SelectedItem==null)return;var p=(LocalGlossaryProfile)profiles.SelectedItem;name.Text=p.Name;context.Text=p.Context;english.Checked=p.UseEnglishReference;terms.Rows.Clear();foreach(var term in p.Terms)terms.Rows.Add(term.Source,term.Target);};var settings=LocalTranslation.Options(run);enabled.Checked=settings.UseGlossary;foreach(var p in LocalLibrary.Profiles(run.Language))profiles.Items.Add(p);profiles.SelectedItem=profiles.Items.Cast<LocalGlossaryProfile>().First(x=>x.Id==LocalLibrary.Profile(run,settings).Id);Resize+=delegate{Arrange();};FormClosing+=delegate(object sender,FormClosingEventArgs e){if(busy){e.Cancel=true;status.Text="Wait for the current profile operation to finish.";}};Arrange();
 }
 void Arrange(){int w=ClientSize.Width,h=ClientSize.Height;profiles.SetBounds(22,18,w-44,30);name.SetBounds(22,62,w-44,28);context.SetBounds(22,105,w-44,112);english.SetBounds(22,230,w-44,26);enabled.SetBounds(22,264,w-44,26);terms.SetBounds(22,305,w-44,h-420);refresh.SetBounds(22,h-95,300,36);save.SetBounds(w-242,h-95,220,36);status.SetBounds(22,h-44,w-44,36);}
 async Task Save(){if(busy)return;terms.EndEdit();var old=(LocalGlossaryProfile)profiles.SelectedItem;var profile=new LocalGlossaryProfile{Id=old.Language=="*"?old.Id+"-"+run.Language:old.Id,Name=name.Text.Trim(),Language=run.Language,Context=context.Text,UseEnglishReference=english.Checked};foreach(DataGridViewRow row in terms.Rows)if(!row.IsNewRow)profile.Terms.Add(new LocalGlossaryTerm{Source=Convert.ToString(row.Cells[0].Value),Target=Convert.ToString(row.Cells[1].Value)});bool use=enabled.Checked;busy=true;save.Enabled=false;try{await Task.Run(()=>{LocalLibrary.SaveProfile(profile);var options=LocalTranslation.Options(run);options.GlossaryProfileId=profile.Id;options.UseGlossary=use;options.ReferenceEnglish=profile.UseEnglishReference;LocalTranslation.SetOptions(run.Id,options);});status.Text="Saved. New requests use this profile; existing text is retained. Refresh affected entries optionally.";}finally{busy=false;save.Enabled=true;}}
}
